import { BrowserRouter, Routes, Route, Link } from "react-router-dom";
import Perfil from "./pages/Perfil";
import Cadastro from "./pages/Cadastro";
import Editar from "./pages/Editar";
import ListarTodos from "./pages/ListarTodos";
import "bootstrap/dist/css/bootstrap.min.css";

function App() {
  return (
    <BrowserRouter>
      <div className="container py-4">
        <h2 className="mb-4">Perfil de Usuário</h2>
        <nav className="mb-4">
          {/* <Link className="btn btn-primary me-2" to="/">Listar Usuarios</Link>
          <Link className="btn btn-success me-2" to="/cadastrar">Cadastrar</Link>
          <Link className="btn btn-warning" to="/editar">Editar</Link> */}
        </nav>
      <Routes>
  <Route path="/" element={<ListarTodos />} />
 <Route path="/usuarios/:id" element={<Perfil />} />
  <Route path="/cadastrar" element={<Cadastro />} />
  <Route path="/editar/:id" element={<Editar />} />
</Routes>
      </div>
    </BrowserRouter>
  );
}

export default App;
